function werkSection() {
  const w = text.werk;
  const filterLabels = {
    all:                     "All",
    enneagramm:              "Enneagram",
    homoeopathie:            "Homeopathy",
    "persoenliche-entwicklung": "Personal Development",
    kalender:                "Calendar",
  };
  const filterBar = Object.entries(filterLabels).map(([key, label]) =>
    `<button class="werk-filter${key === "all" ? " is-active" : ""}" data-werk-filter="${key}">${label}</button>`
  ).join("");

  const cards = werkRegister.map((book) => {
    const isPending = book.status === "link_pruefen";
    const linkLabel = book.category === "kalender" ? "To the Calendar" : book.id.includes("hoerbuch") ? "To the Audiobook" : w.openBook;
    const verlagsLink = isPending
      ? `<span class="deepen-link deepen-link--pending">${w.linkPending}</span>`
      : `<a class="deepen-link" href="${book.link}" target="_blank" rel="noopener">${linkLabel} →</a>`;
    const bodLink = !isPending && book.bodUrl
      ? `<a class="deepen-link deepen-link--bod" href="${book.bodUrl}" target="_blank" rel="noopener">Buy at BoD →</a>`
      : "";
    const coverImg = `<img src="${CDN}assets/covers/${book.id}.jpg" alt="" loading="lazy"
      onerror="this.parentElement.style.display='none'"
      style="width:60px;flex-shrink:0;border-radius:4px;object-fit:cover;align-self:flex-start;box-shadow:0 1px 4px rgba(0,0,0,.18);">`;
    return `
      <article class="werk-card" data-category="${book.category || ""}" style="display:flex;gap:.75rem;align-items:flex-start;">
        <div style="width:60px;flex-shrink:0;">${coverImg}</div>
        <div style="min-width:0;">
          <h3 style="margin-top:0;">${book.title}</h3>
          <p class="werk-card__themes">${w.themes}: ${book.themes.join(" · ")}</p>
          <div class="werk-card__links">${verlagsLink}${bodLink}</div>
        </div>
      </article>`;
  }).join("");

  return `
    <section class="werk">
      <div class="section-divider"><span>${w.title}</span></div>
      <p class="lead-small werk__lead">${w.lead}</p>
      <div class="werk-filterbar">${filterBar}</div>
      <div class="werk-grid">${cards}</div>
    </section>
  `;
}

// ── QUIZ ENGINE ──────────────────────────────────────────────────────────

function _quizSeededRng(seed) {
  let s = (seed >>> 0) || 1;
  return function() {
    s ^= s << 13; s ^= s >>> 17; s ^= s << 5;
    return (s >>> 0) / 0xffffffff;
  };
}

function _quizShuffleAnswers(question, rng) {
  const items = question.a.map((text, i) => ({ text, correct: i === question.c }));
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

function _quizPickQuestions(seed) {
  const qd = window._quizData || [];
  const rng = _quizSeededRng(seed);
  const pick = (pool, n) => {
    const arr = pool.slice().sort(() => rng() - 0.5);
    return arr.slice(0, Math.min(n, arr.length));
  };
  const leicht = qd.filter(q => q.d === "leicht");
  const mittel = qd.filter(q => q.d === "mittel");
  const schwer = qd.filter(q => q.d === "schwer");
  const chosen = [...pick(leicht, 4), ...pick(mittel, 4), ...pick(schwer, 2)];
  return chosen.sort(() => rng() - 0.5);
}

window._startQuiz = function() {
  try {
    const seed = Date.now() & 0xffffffff;
    const rng  = _quizSeededRng(seed);
    const questions = _quizPickQuestions(seed);
    if (!questions || !questions.length) {
      alert("Quiz-Daten nicht geladen. Bitte Seite neu laden.");
      return;
    }
    _quizState = {
      phase: "question",
      questions,
      current: 0,
      score: 0,
      answered: false,
      selectedIdx: null,
      shuffledAnswers: _quizShuffleAnswers(questions[0], rng),
      seed,
    };
    if (location.hash === "#quiz") { render(); } else { location.hash = "quiz"; }
  } catch(e) {
    alert("Quiz-Error: " + e.message);
  }
};

window._answerQuiz = function(idx) {
  if (!_quizState || _quizState.answered) return;
  _quizState.answered = true;
  _quizState.selectedIdx = idx;
  if (_quizState.shuffledAnswers[idx].correct) _quizState.score++;
  if (location.hash === "#quiz") { render(); } else { location.hash = "quiz"; }
};

window._nextQuizQuestion = function() {
  if (!_quizState) return;
  _quizState.current++;
  if (_quizState.current >= _quizState.questions.length) {
    _quizState.phase = "result";
  } else {
    _quizState.answered = false;
    _quizState.selectedIdx = null;
    const rng = _quizSeededRng((Date.now() ^ (_quizState.current * 2654435761)) >>> 0);
    _quizState.shuffledAnswers = _quizShuffleAnswers(_quizState.questions[_quizState.current], rng);
  }
  if (location.hash === "#quiz") { render(); } else { location.hash = "quiz"; }
};

window._resetQuiz = function() {
  _quizState = null;
  if (location.hash === "#quiz") { render(); } else { location.hash = "quiz"; }
};


// ── Globale Search ────────────────────────────────────────────────────────────────────────────

function _sucheResults(q) {
  const lq = q.toLowerCase();
  const res = { subtypen: [], portraits: [], register: [], zitate: [] };

  Object.values(subtypeProfiles).forEach(p => {
    const hay = [p.code, p.title_en || p.title, p.titleAlt, p.archetype, p.subtitle || ""].join(" ").toLowerCase();
    if (hay.includes(lq)) {
      res.subtypen.push({ label: enCode(p.code) + " – " + (p.title_en || p.title), sub: p.archetype_en || p.archetype || "", route: "subtype/" + p.id });
    }
  });

  KRIMINAL_PORTRAITS.forEach(p => {
    const hay = (p.name + " " + (p.beschreibung || "") + " " + (p.typ || "")).toLowerCase();
    if (hay.includes(lq)) res.portraits.push({ label: p.name, sub: p.typ || "", route: p.route });
  });

  registerEntriesEN.forEach(e => {
    const hay = (e.term + " " + (e.description || "")).toLowerCase();
    if (hay.includes(lq)) res.register.push({ label: e.term, sub: (e.description || "").slice(0, 80), route: e.route });
  });

  (window._zitateData || []).forEach(z => {
    const hay = (z.q + " " + z.a + " " + (z.t || "")).toLowerCase();
    if (hay.includes(lq)) {
      const label = '"' + z.q.slice(0, 65) + (z.q.length > 65 ? "…" : "") + '"';
      res.zitate.push({ label, sub: z.a + (z.y ? " (" + z.y + ")" : ""), route: "zitate" });
    }
  });

  return res;
}

function _sucheResultsHtml(res, q) {
  const total = res.subtypen.length + res.portraits.length + res.register.length + res.zitate.length;
  if (total === 0) return `<p class="suche-hint">No results found for &ldquo;${q}&rdquo;.</p>`;

  const hl = (txt) => {
    const i = txt.toLowerCase().indexOf(q.toLowerCase());
    if (i === -1) return txt;
    return txt.slice(0, i) + `<mark class="suche-hl">${txt.slice(i, i + q.length)}</mark>` + txt.slice(i + q.length);
  };

  const group = (title, items) => {
    if (!items.length) return "";
    const more = items.length > 6 ? `<p class="suche-more">+ ${items.length - 6} weitere</p>` : "";
    return `<div class="suche-group">
      <h3 class="suche-group-title">${title} <span class="suche-count">${items.length}</span></h3>
      ${items.slice(0, 6).map(it => `<button class="suche-result" data-route="${it.route}">
        <span class="suche-result-label">${hl(it.label)}</span>
        ${it.sub ? `<span class="suche-result-sub">${it.sub}</span>` : ""}
      </button>`).join("")}${more}</div>`;
  };

  return `<p class="suche-total">${total} Ergebnis${total === 1 ? "" : "se"}</p>
    ${group("Subtypes", res.subtypen)}
    ${group("Kriminalporträts", res.portraits)}
    ${group("Register &amp; Charts", res.register)}
    ${group("Quotes of the Wise", res.zitate)}`;
}

window._updateSearch = function(q) {
  _sucheQuery = q;
  const box = document.getElementById("suche-ergebnisse");
  if (!box) return;
  if (q.length < 2) { box.innerHTML = `<p class="suche-hint">Mindestens 2 Zeichen eingeben…</p>`; return; }
  const res = _sucheResults(q);
  box.innerHTML = _sucheResultsHtml(res, q);
  box.querySelectorAll("[data-route]").forEach(btn => {
    btn.addEventListener("click", () => { _sucheQuery = ""; go(btn.dataset.route); });
  });
};

function suchePage() {
  const hasQ = _sucheQuery.length >= 2;
  return shell(`
    ${pageHeader("suche")}
    <section class="narrow suche-page" style="padding:1.5rem 1rem 4rem;">
      <div class="suche-box">
        <svg class="suche-box-icon" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input class="suche-input" id="suche-input" type="search"
               placeholder="Subtypes, Portraits, Charts, Quotes…"
               oninput="window._updateSearch(this.value)"
               value="${_sucheQuery.replace(/"/g, '&quot;')}"
               autocomplete="off" spellcheck="false" />
      </div>
      <div id="suche-ergebnisse">
        ${hasQ ? _sucheResultsHtml(_sucheResults(_sucheQuery), _sucheQuery) : `<p class="suche-hint">Mindestens 2 Zeichen eingeben…</p>`}
      </div>
    </section>
  `);
}


function frankAbagnalePortraitPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Frank Abagnale Jr. – Criminal Psychology")}
      <div id="js-back-target" data-route="kriminalpsychologie" style="display:none;"></div>
      <div class="krim-portrait-wrap">
        <div class="krim-portrait-frame">
          <img src="../assets/portraits/frank-abagnale-portrait.jpg" alt="Frank Abagnale Jr. – Portrait" class="krim-portrait-img" loading="lazy" />
        </div>
        <p class="krim-portrait-name">Frank Abagnale Jr.</p>
        <p class="krim-portrait-typ">SO7w6 · Social Type 7 with Six-wing</p>
        <p style="color:var(--muted);font-size:0.9rem;margin:0;">American Impostor and Con Artist · Animal correspondence: Beaver</p>
      </div>

      <p class="psycho-intro">
        <strong>Frank William Abagnale Jr.</strong>, born on April 27, 1948, in Bronxville, New York, is considered one of the most skillful impostors in criminal history. When his parents divorced—he was sixteen—he ran away from home and began an unprecedented career as a con artist: between 1964 and 1969 he posed as a Pan Am pilot, a pediatric resident, a Louisiana state prosecutor, and an FBI agent. He allegedly cashed forged checks worth around $2.5 million across twenty-six countries. In 1969 he was arrested in France, incarcerated in several countries, and eventually extradited to the United States. Following his release, he worked for decades as a security consultant for banks and government agencies. Steven Spielberg's film "Catch Me If You Can" (2002) brought worldwide fame to his story. Later investigative journalism questioned parts of his biography — suggesting that the story of the world's greatest impostor might itself be an imposture.
      </p>

      <div class="vb-section" style="background:rgba(232,146,42,0.08);border-left:3px solid #e8922a;padding:1rem 1.2rem;border-radius:8px;margin-bottom:2rem;max-width:100%;">
        <p style="margin:0;font-size:0.95rem;color:var(--ink);"><strong>Type Assignment:</strong> <strong>Frank Abagnale Jr.</strong> is assigned to the <strong>Social Type 7 with Six-wing (SO7w6)</strong> in the Enneagram. Naranjo calls this subtype <em>Sacrifice</em>: the social Seven forgoes the unrestrained hedonism of the other Seven subtypes and instead places itself, seemingly selflessly, in service of a larger system, a group, a mission. Yet the renunciation is itself a performance: making yourself indispensable secures access to ever more stages, roles, and possibilities. In Abagnale's case, this showed as a restless search for new systems he could join as a useful, valued member — an airline, a hospital, a law firm, and finally the FBI itself. The Six-wing adds an extra layer of security orientation: the need to test authorities and systems for trustworthiness, and a deep longing to eventually be accepted, himself, as trustworthy within a stable system.</p>
      </div>

      <div class="vb-section" style="max-width:100%;">
        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">1. Animal Correspondence: The Beaver</h3>
        <p class="vb-intro">The <strong>Beaver</strong> is the animal correspondence of the Social Seven — a builder, not a loner. It doesn't waste energy going it alone; it constructs structures that serve a larger purpose: the dam, the lodge, the network of channels that reshapes an entire ecosystem. It is busy, resourceful, optimistic — and constantly occupied with building itself into a system that will carry it and in which it becomes indispensable. Abagnale was this beaver: he didn't build himself into a role in order to disappear, but in order to become part of a functioning whole — an airline, a hospital, a law firm, a federal agency. Every new identity was a new dam, a new construction project through which he secured belonging and freedom of movement at once.</p>
      </div>

      <div class="vb-section" style="max-width:100%;">
        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">2. Facial & Gaze Expression Quality</h3>
        <p class="vb-intro"><strong>a) Charming, Quick-Tongued, Instantly Likeable:</strong> Abagnale never came across as a showman triggering suspicion, but as someone you warmed to immediately — engaging, talkative, carrying an optimistic ease that never let skepticism take hold. This is the social Seven in its purest form: charm as a passport into any system.</p>
        <p class="vb-intro"><strong>b) Always Another Option Up His Sleeve:</strong> Contemporaries described him as quick-thinking and never at a loss for an excuse or an exit. Whenever an identity grew too tight or too risky, the next one was already prepared. This ability never to feel cornered mentally is a core trait of the Seven — in the social variant paired with the conviction that the next step should also serve the larger whole, not just personal pleasure.</p>
        <p class="vb-intro"><strong>c) The Six-Wing: Testing Authority, Seeking Safety:</strong> Unlike a pure Seven who simply drifts, Abagnale carefully studied the systems he infiltrated for their rules, weak points, and trust mechanisms — a typical Six-like vigilance. And that very vigilance eventually led him exactly where he never wanted to go and yet needed most: into a system he could genuinely trust.</p>
      </div>

      <div class="vb-section" style="max-width:100%;">
        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">3. General Characteristics</h3>
        <p class="vb-intro"><strong>a) Variety Over Security as Primary Motivation:</strong> Abagnale didn't switch identities primarily out of fear for his survival, but because each role eventually exhausted its possibilities. Pilot: free access to the whole world. Doctor: belonging to a respected institution. Lawyer: insight into another powerful system. This is Seven-like logic — the world has so many doors, why keep only one open?</p>
        <p class="vb-intro"><strong>b) Service to the System as Disguise — the SO7's Sacrifice Principle:</strong> The social Seven sells its restlessness as a contribution to the whole: it is the useful one, the competent one, the one without whom things wouldn't run smoothly. That's exactly what Abagnale did — he presented himself as a helpful, functioning member of every institution he infiltrated, and was rewarded with trust, access, and freedom of movement. Unlike a Three seeking admiration for personal achievement, Abagnale wanted, above all, to be needed without being tied down.</p>
        <p class="vb-intro"><strong>c) The Six-Wing: Searching for the One Reliable System:</strong> What distinguishes the SO7 from a more carefree Seven expression is an undercurrent of restlessness: the need for a system truly worthy of trust. This wing explains why Abagnale never really settled, even though he seemingly had everything — access, status, admiration. He wasn't chasing the next thrill. He was searching for the one place where his abilities would be legitimately needed. In the end, he found it in the very place he had once feared most: the agency that had hunted him.</p>
      </div>

      <div class="vb-section" style="max-width:100%;">
        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">4. Concrete Acts & Exploits</h3>
        <p class="vb-intro"><strong>a) The Pan Am Uniform via Telephone:</strong> Abagnale started his career with a single phone call. He called Pan American World Airways, claiming his uniform had been lost. They named the supplier — the rest was routine. Equipped with a uniform and a fake pilot ID, he presented himself at counters asking for deadhead flights (free seats for traveling crew members). For over two years he flew to 26 countries. Lodging and meals were billed to Pan Am's corporate office. A new territory, a new dam — the whole world as his playground.</p>
        <p class="vb-intro"><strong>b) A Year as a Pediatric Resident in Georgia:</strong> Posing as Dr. Frank Adams — a pediatrician fresh out of New York — he was hired as the supervising physician for medical students. For nearly a year he signed medical charts and organized his daily routine so that he never had to treat a patient directly at the bedside. When an Irish colleague sought a genuine, deeper friendship, Abagnale sidestepped it — closeness that might have tied him down made him uneasy.</p>
        <p class="vb-intro"><strong>c) Lawyer in Louisiana — Passing the Bar on the Third Try:</strong> Abagnale forged a Harvard transcript and passed the state bar exam on his third attempt. No panic, no giving up — just the Seven's optimistic persistence, which treats every setback as merely a temporary hurdle on the way to the next open door. He worked for nearly a year as an Assistant Attorney General until a real Harvard graduate joined the firm.</p>
        <p class="vb-intro"><strong>d) Check Fraud on an Industrial Scale:</strong> Abagnale inflicted the greatest financial damage through forged checks. He printed checks using authentic routing numbers and cashed them worldwide using his pilot ID — at hotels, banks, and currency exchanges. A system, expanded into ever more countries and channels — beaver business on a grand scale.</p>
        <p class="vb-intro"><strong>e) Arrest, Escape, Rearrest:</strong> In 1969 an Air France flight attendant recognized him in Montpellier. He was incarcerated in France, Sweden, and the United States. He escaped from a Swedish prison by posing as a US prison inspector. In the US, he convinced a guard that he was working undercover for the Department of Justice. Even behind bars, his mindset remained: which role opens the next door here?</p>
        <p class="vb-intro"><strong>f) From Offender to FBI Consultant:</strong> Following a prison term, Abagnale struck a deal with the FBI: he assisted in capturing check counterfeiters and became a sought-after expert on document fraud. This is the SO7w6 resolution in its purest form: the endless search for the next system finally settling into a belonging he could genuinely trust — legitimate, needed, finally arrived.</p>
      </div>

      <div class="vb-section" style="max-width:100%;">
        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">5. Offender Profile & Psychological Classification</h3>
        <p class="vb-intro"><strong>a) Not a Narcissist — A Restless Optimist:</strong> Abagnale wasn't chasing a stage for applause, nor quiet control over resources. He was chasing movement, variety, and a sense of being needed without ever being pinned down. This makes him atypical for the image of the cold con artist: his energy read more like unbridled enthusiasm than calculation.</p>
        <p class="vb-intro"><strong>b) Biography as One Last Story:</strong> Later investigations exposed parts of his self-narrative as exaggerated or invented. This, too, fits the SO7w6: the Seven likes to tell its own story bigger, brighter, and more significant than it may have been — not out of calculation, but because optimistically reframing one's own past is part of its basic pattern.</p>
        <p class="vb-intro"><strong>c) Distinguishing Him From Other Impostors:</strong> Unlike Self-Preservation Three con artists such as Bernie Madoff or Ruja Ignatova, who above all sought quiet control over resources or a perfectly guarded stage, Abagnale was never after a single, carefully tended system. He wanted to keep many doors open, enter many systems — and be briefly indispensable in each of them. That is the key difference between the SP3's quiet resource logic and the SO7w6's restless, system-seeking logic.</p>
      </div>

      <div class="vb-section" style="background:rgba(232,146,42,0.07);border-left:3px solid #e8922a;padding:1rem 1.2rem;border-radius:8px;margin-bottom:2rem;max-width:100%;">
        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 0.75rem;color:var(--ink);">Summary</h3>
        <p style="margin:0 0 0.6rem;font-size:0.95rem;color:var(--ink);">
        Frank Abagnale Jr. represents the SO7w6 in its pathological purity: a person who understood identity not as self-expression, but as a passport into ever-new systems where he could feel useful, welcome, and alive. His passion of gluttony shows up not as excess or pleasure-seeking, but as a restless variety of roles, places, and institutions, none of which ever held him long enough.</p>
        <p style="margin:0 0 0.6rem;font-size:0.95rem;color:var(--ink);">
        The Six-wing never let him fully settle. Behind every new role waited the same question: is this finally a system I can trust? Only in alliance with the FBI — the very system that once hunted him — did he find an answer he could live with.</p>
        <p style="margin:0;font-size:0.95rem;color:var(--ink);">
        The beaver keeps building until the ecosystem around it is complete. But does it also build something that carries itself? That is the question Abagnale's life poses — one he only half-answered, late, with the FBI at his side.</p>
      </div>

    </div>
  `);
}
