function spuerenInner(entry, sp) {
  const blocks = [];
  // Profilbild (Seite 1) — zeigt Prototypen, Blickqualität, Körpersignatur
  const seite1 = `${CDN}assets/knowledge/type-${entry.code.slice(-1)}/${entry.code.toLowerCase()}/${entry.code.toLowerCase()}-page-1.jpeg`;
  blocks.push(`
    <figure class="vollseite-karte">
      <p class="vollseite-karte__hint">Tap to enlarge</p>
      <div class="card-pg-wrap">
        <img src="${seite1}" alt="${entry.code} Seite 1 &ndash; Prototypen, Blickqualität und Körpersignatur" class="vollseite-karte__img" loading="lazy"
          onerror="this.closest('.vollseite-karte').style.display='none'" />
        <div class="card-pg-compass" aria-hidden="true">${compassMark("mini")}</div>
      </div>
      <figcaption class="vollseite-karte__titel">Page 1 · Profile, Prototypes & Body Signature</figcaption>
    </figure>
  `);
  blocks.push(page1SummaryBlock(entry.code));
  const bs = entry.bodySignature;
  const bsl = sp.bodySignature || {};
  if (bs) {
    const tpEn = TWOPOINTS_EN[(entry.code || "").toLowerCase()] || null;
    const tpSrc = tpEn || bs.twoPoints || null;
    if (tpSrc) {
      const pts = [tpSrc.point1, tpSrc.point2].filter(Boolean);
      if (pts.length) {
        const ptHtml = pts.map((p) => `<li><strong>${p.name}</strong> (${p.location})${p.need && p.need.length ? `<ul>${p.need.map((n) => `<li>${n}</li>`).join("")}</ul>` : ""}</li>`).join("");
        blocks.push(`<div class="room-field"><strong>Two-Point Integration</strong><ul>${ptHtml}</ul></div>`);
      }
      if (tpSrc.microInstructions && tpSrc.microInstructions.length) blocks.push(`<div class="room-field"><strong>Micro-Instructions</strong><ul>${tpSrc.microInstructions.map((i) => `<li>${i}</li>`).join("")}</ul></div>`);
    }
  }
  if (entry.archetypalEssence) blocks.push(`<div class="room-field"><strong>${sp.archetypalEssence || "Archetypische Essenz"}</strong><p>${entry.archetypalEssence}</p></div>`);
  if (entry.integrativePotential) blocks.push(`<div class="room-field"><strong>${sp.integrativePotential || "Integratives Potenzial"}</strong><p>${entry.integrativePotential}</p></div>`);
  const enQ = (SUBTYPES_EN[(entry.code||"").toLowerCase()]||{}).essenceQualities; if (enQ || (entry.essence && entry.essence.qualities)) blocks.push(`<div class="room-field"><strong>${sp.essenceQualities}</strong><ul>${(enQ || entry.essence.qualities).map((i) => `<li>${i}</li>`).join("")}</ul></div>`);
  return blocks.join("");
}

function koerperarbeitBlock(k) {
  if (!k || !k.seiten) return "";
  return k.seiten.map(s => `
    <figure class="vollseite-karte">
      <p class="vollseite-karte__hint">Tap to enlarge</p>
      <div class="card-pg-wrap">
        <img src="${s.src}" alt="${s.alt}" class="vollseite-karte__img" loading="lazy" />
        <div class="card-pg-compass" aria-hidden="true">${compassMark("mini")}</div>
      </div>
      <figcaption class="vollseite-karte__titel">${s.titel}</figcaption>
    </figure>
  `).join("");
}

function regulierenInner(entry, sp) {
  const blocks = [];
  // Alle Charts außer Seite 1 (die bereits in spuerenInner gezeigt wird)
  // visualPages ersetzt koerperarbeit.seiten für alle 27 Subtypes vollständig
  if (entry.visualPages && entry.visualPages.length > 1) {
    const remaining = entry.visualPages.filter(pg => !pg.src.includes("page-1"));
    remaining.forEach(pg => blocks.push(`
      <figure class="vollseite-karte">
        <p class="vollseite-karte__hint">Tap to enlarge</p>
        <div class="card-pg-wrap">
          <img src="${pg.src}" alt="${pg.alt}" class="vollseite-karte__img" loading="lazy"
            onerror="this.closest('.vollseite-karte').style.display='none'" />
          <div class="card-pg-compass" aria-hidden="true">${compassMark("mini")}</div>
        </div>
        <figcaption class="vollseite-karte__titel">${pg.title || pg.titel || ""}</figcaption>
      </figure>
    `));
  }
  const enReg = SUBTYPES_EN[(entry.code || "").toLowerCase()] || {}; if ((enReg.turningPoint || (entry.turningPoint && entry.turningPoint.length))) blocks.push(`<div class="room-field"><strong>${sp.turningPoint || "Turning Point"}</strong><ul>${(enReg.turningPoint || entry.turningPoint).map((i) => `<li>${i}</li>`).join("")}</ul></div>`);
  const enNsr = NSR_EN[(entry.code || "").toLowerCase()];
  if (enNsr || (entry.nervousSystemRegulation && entry.nervousSystemRegulation.length)) blocks.push(`<div class="room-field"><strong>${sp.nervousSystemRegulation || "Nervous System Regulation"}</strong><ul>${(enNsr || entry.nervousSystemRegulation).map((i) => `<li>${i}</li>`).join("")}</ul></div>`);
  if ((enReg.tensionFields || (entry.tensionFields && entry.tensionFields.length))) blocks.push(`<div class="room-field"><strong>${sp.tensionFields || "Tension Fields"}</strong><ul>${(enReg.tensionFields || entry.tensionFields).map((i) => `<li>${i}</li>`).join("")}</ul></div>`);
  if (entry.practice) blocks.push(`<div class="room-field"><strong>${sp.practice}</strong><p>${entry.practice}</p></div>`);
  blocks.push(`
    <div class="room-field" style="margin-top:1.4rem;padding:1.1rem 1.2rem;background:var(--paper);border-radius:12px;border-left:3px solid var(--gold);text-align:left;">
      <p style="margin:0 0 0.5rem;font-size:0.88rem;color:var(--ink-muted);line-height:1.6;">Once you have recognised the patterns of this subtype — let what you have read settle now. No further analysis. Simply be.</p>
      <button class="ghost-link" data-route="stille" style="font-size:0.95rem;">⏱ 9 minutes of stillness →</button>
    </div>
  `);
  return blocks.join("");
}

function verkoerpernInner(entry, sp) {
  const hasMedia = entry.mediaGroups || entry.mediaResources;
  if (hasMedia && !hasHeilwissen()) return heilwissenLock("Musik & Klang");
  if (entry.mediaGroups) return mediaGroupSection(entry.mediaGroups);
  if (entry.mediaResources) return mediaResourceSection(entry.mediaResources);
  return `<p class="room-pending">${sp.mediaPending}</p>`;
}


const MEDIA_CATEGORY_EN = {
  "Praxis": "Practice",
  "Vertiefung": "Deepening",
  "Fl\u00fcgel": "Wing",
  "Affirmationen": "Affirmations",
  "Musik": "Music",
  "Wissen": "Knowledge",
  "Playlist": "Playlist",
  "Song 1": "Song 1",
  "Song 2": "Song 2",
  "Song 3": "Song 3",
  "Song 4": "Song 4",
  "Song 5": "Song 5",
};

function translateHinweis(werkId, hinweis) {
  var m;
  m = hinweis.match(/Das vollst.ndige (\S+)-Subtypprofil und die Dynamik innerhalb von Typ (\d+)\./);
  if (m) return "The complete " + m[1] + " subtype profile and the dynamics within Type " + m[2] + ".";
  m = hinweis.match(/Schritt.+herausfinden, ob Typ (\d+) \/ (\S+) zu dir passt\./);
  if (m) return "Step by step, find out whether Type " + m[1] + " / " + m[2] + " fits you.";
  m = hinweis.match(/Hintergrund zum Edelstein (.+?) und den Enneagrammprinzipien\./);
  if (m) { var sEN = GERMAN_REMEDY_NAMES_EN[m[1]] || m[1]; return "Background on the healing stone " + sEN + " and Enneagram principles."; }
  m = hinweis.match(/Die Wunde hinter der Leidenschaft des Typ (\d+)/);
  if (m) return "The wound behind the passion of Type " + m[1] + " (Chapter Type " + m[1] + ").";
  m = hinweis.match(/Die fr.he Pr.gung hinter dem Muster des Typ (\d+)\./);
  if (m) return "The early imprint behind the pattern of Type " + m[1] + ".";
  m = hinweis.match(/Wie Burnout bei Typ (\d+) entsteht/);
  if (m) return "How burnout in Type " + m[1] + " develops, what it feels like, and how it can be overcome - type-specific warning signs and prevention.";
  return hinweis;
}

function translateGroupTitle(title) {
  return title
    .replace(/Seite (\d+) \u00b7 Praxis, Vertiefung und Songs/, "Page $1 \u00b7 Practice, Deepening and Songs")
    .replace(/Seite (\d+) \u00b7 Subtyp-Profil/, "Page $1 \u00b7 Subtype Profile")
    .replace(/Seite (\d+) \u00b7 2-Punkte-Integration/, "Page $1 \u00b7 Two-Point Integration")
    .replace(/Seite (\d+) \u00b7 K.rperarbeit & Akupressur/, "Page $1 \u00b7 Bodywork & Acupressure")
    .replace(/Seite (\d+) \u00b7 Heilmittel-Kompass/, "Page $1 \u00b7 Remedy Compass")
    .replace(/Seite (\d+) \u00b7 Integrationspotenzial/, "Page $1 \u00b7 Integration Potential")
    .replace(/Seite (\d+) \u00b7 Transformation/, "Page $1 \u00b7 Transformation")
    .replace(/Seite (\d+) \u00b7 Integration$/, "Page $1 \u00b7 Integration")
    .replace(/\u00b7 Seite (\d+)$/, "\u00b7 Page $1");
}

function translateGroupNote(note) {
  if (note && note.indexOf("Medienblock mit Praxis- und Vertiefungslinks") !== -1) {
    return "Media block with practice and deepening links, wing video, and song and affirmation fields.";
  }
  if (note && note.indexOf("Diese Gruppe entspricht dem Medienblock auf Seite 3") !== -1) {
    return "This group corresponds to the media block on page 3: practice links, wing video, and the six song/affirmation fields.";
  }
  return note || "";
}

function translateMediaTitle(title) {
  if (!title) return title;
  return title
    .replace("Spezielle Bewusstseins\u00fcbungen f\u00fcr die 9 Enneagrammtypen", "Special Consciousness Exercises for the 9 Enneagram Types")
    .replace("Dynamische Darstellung der 9 Enneagrammtypen von Detlef Rathmer", "Dynamic Presentation of the 9 Enneagram Types by Detlef Rathmer")
    .replace("Playlist zur Bewusstseinserweiterung", "Playlist for Expanding Consciousness")
    .replace("Fl\u00fcgel-Video", "Wing Video")
    .replace("mit 9er- und 2er-Fl\u00fcgel", "with Nine-Wing and Two-Wing")
    .replace("deutscher Themensong", "German Theme Song")
    .replace("deutscher subtypspezifischer Song", "German Subtype-Specific Song")
    .replace("englischer subtypspezifischer Song", "English Subtype-Specific Song")
    .replace("archetypisch-biblischer Song", "Archetypal-Biblical Song")
    .replace("100 heilsame Affirmationen", "100 Healing Affirmations")
    .replace("Songs zum Wesen der Hom\u00f6opathie", "Songs on the Nature of Homeopathy")
    .replace("Zur Wirkweise der Enneagramm-Hom\u00f6opathie", "On the Mechanism of Enneagram Homeopathy")
    .replace("Zur Wirkweise der Hom\u00f6opathie", "On the Mechanism of Homeopathy")
    .replace("Alles muss stimmen", "Everything Must Be Right")
    .replace("englischer Song:", "English Song:")
    .replace("deutscher Song:", "German Song:")
    .replace(/\bTyp (\d+) \u00b7/g, "Type $1 \u00b7")
    .replace(/\bTyp (\d+) mit\b/g, "Type $1 with");
}

function translateScope(scope) {
  if (!scope) return scope;
  return scope.replace(/^Typ /, "Type ").replace("Hom\u00f6opathie", "Homeopathy");
}

function vertiefungSection(refs, sp) {
  if (!refs || !refs.length) return "";
  const byId = Object.fromEntries(werkRegister.map((b) => [b.id, b]));
  return `
    <p class="deepen-intro">${sp.deepenIntro}</p>
    <ul class="deepen-list">
      ${refs
        .map((ref) => {
          const book = byId[ref.werkId];
          if (!book) return "";
          const link = book.status === "link_pruefen"
            ? `<span class="deepen-link deepen-link--pending">${sp.linkPending}</span>`
            : `<a class="deepen-link" href="${book.link}" target="_blank" rel="noopener">${sp.openBook} →</a>`;
          return `
            <li class="deepen-item">
              <strong>${book.title}</strong>
              <p>${translateHinweis(ref.werkId, ref.hinweis)}</p>
              ${link}
            </li>`;
        })
        .join("")}
    </ul>
  `;
}

const TYPE_COLORS = {
  1: "#5f5f5f", 2: "#7a2fa8", 3: "#1fa688", 4: "#3cbf1f",
  5: "#124fcc", 6: "#8a5222", 7: "#d4a800", 8: "#a00802", 9: "#cc6e00"
};
function typeColor(num) { return TYPE_COLORS[parseInt(num)] || "var(--copper)"; }
function typeColorFromCode(code) { return typeColor(code ? code.slice(-1) : 0); }

const GRUNDTYPEN = [
  { num: 1, name: "The Perfectionist",   label: "The Order-Oriented",      leidenschaft: "Anger",    tier: "Eagle",    thema: "Right & Wrong · Integrity & Order",     codes: ["se1","so1","sx1"] },
  { num: 2, name: "The Helper",          label: "The Relationship-Oriented",    leidenschaft: "Pride",   tier: "Cat",    thema: "Love & Recognition · Giving & Receiving", codes: ["se2","so2","sx2"] },
  { num: 3, name: "The Achiever",         label: "The Success-Oriented",       leidenschaft: "Vanity / Deceit",    tier: "Peacock",     thema: "Success & Worth · Achievement & Recognition",       codes: ["se3","so3","sx3"] },
  { num: 4, name: "The Individualist",   label: "The Identity-Oriented",    leidenschaft: "Envy",    tier: "Horse",    thema: "Authenticity & Depth · Loss & Longing",        codes: ["se4","so4","sx4"] },
  { num: 5, name: "The Observer",         label: "The Knowledge-Oriented",       leidenschaft: "Avarice",    tier: "Owl",     thema: "Knowledge & Understanding · Withdrawal & Resources",     codes: ["se5","so5","sx5"] },
  { num: 6, name: "The Loyalist",         label: "The Security-Oriented",   leidenschaft: "Fear",   tier: "Hare",     thema: "Security & Trust · Danger & Loyalty",   codes: ["se6","so6","sx6"] },
  { num: 7, name: "The Enthusiast",      label: "The Possibility-Oriented",  leidenschaft: "Gluttony", tier: "Monkey", thema: "Joy & Abundance · Options & Avoidance",      codes: ["se7","so7","sx7"] },
  { num: 8, name: "The Challenger",       label: "The Power-Oriented",         leidenschaft: "Lust", tier: "Lion",     thema: "Strength & Control · Justice & Power",    codes: ["se8","so8","sx8"] },
  { num: 9, name: "The Peacemaker",       label: "The Harmony-Seeker",       leidenschaft: "Sloth",tier: "Elephant",  thema: "Harmony & Peace · Merging & Sleep",   codes: ["se9","so9","sx9"] },
];

function typesPage() {
  const kartenHtml = GRUNDTYPEN.map(t => {
    const c = typeColor(t.num);
    return `
    <button class="typ-karte" data-route="type/${t.num}" style="border-left-color:${c}">
      <span class="typ-karte__num" style="background:${c}">${t.num}</span>
      <div class="typ-karte__body">
        <strong class="typ-karte__name" style="color:${c}">${t.name}</strong>
        <span class="typ-karte__label" style="color:${c}">${t.label}</span>
        <span class="typ-karte__thema">${t.thema}</span>
      </div>
      <span class="typ-karte__arrow" style="color:${c}">→</span>
    </button>`;
  }).join("");
  return shell(`
    ${pageHeader("knowledge")}
    <section class="narrow">
      <p class="eyebrow">Enneagram Healing Compass</p>
      <h1>The 9 Core Types</h1>
      <p class="lead-small">Select your Type to explore the three Subtypes and all content.</p>
    </section>
    <section class="typen-liste">${kartenHtml}</section>
  `);
}

function typePage(num) {
  const t = GRUNDTYPEN.find(x => x.num === parseInt(num));
  if (!t) return typesPage();
  const c = typeColor(t.num);
  const subtypenHtml = t.codes.map(code => {
    const p = subtypeProfiles[code];
    if (!p) return "";
    const instinktLabel = { se: "Self-Preservation", so: "Social", sx: "Sexual / Partnership" }[code.slice(0,2)] || "";
    return `
      <button class="subtyp-karte" data-route="subtype/${code}" style="border-left-color:${c}">
        <div class="subtyp-karte__icon" style="color:${c}">${p.emoji || p.code}</div>
        <div class="subtyp-karte__body">
          <strong style="color:${c}">${p.title_en || p.title}</strong>
          <span>${enCode(p.code)} · ${instinktLabel}</span>
          <em>${p.focus_en || p.focus}</em>
        </div>
        <span class="subtyp-karte__arrow" style="color:${c}">→</span>
      </button>
    `;
  }).join("");
  return shell(`
    ${pageHeader("knowledge")}
    <section class="narrow">
      <button class="ghost-link" data-route="knowledge">← All Types</button>
      <p class="eyebrow" style="color:${c}">Type ${t.num} · ${t.label}</p>
      <h1 style="color:${c}">${t.name}</h1>
      <p class="lead-small">${t.thema}</p>
      <div class="typ-meta">
        <span class="typ-meta__chip" style="border-color:${c};color:${c}">Passion: <strong>${t.leidenschaft}</strong></span>
        <span class="typ-meta__chip" style="border-color:${c};color:${c}">Animal: <strong>${t.tier}</strong></span>
      </div>
      ${impulseBlock(TYP_IMPULSE_EN[t.num] || TYP_IMPULSE[t.num], c)}
    </section>
    <section class="subtypen-liste">${subtypenHtml}</section>
  `);
}

function knowledgePage() {
  const block = knowledgePrototype.typeBlock;
  const copy = text.routes.knowledge;
  return shell(`
    ${pageHeader("knowledge")}
    <section class="knowledge-hero">
      <div>
        <p class="eyebrow">${copy.eyebrow}</p>
        <h1>${copy.headline}</h1>
        <p class="lead-small">${knowledgePrototype.source}</p>
      </div>
      <aside>
        <span>${block.status}</span>
        <strong>${block.title}</strong>
        <p>${block.note}</p>
      </aside>
    </section>
    <section class="knowledge-grid">
      ${knowledgePrototype.subtypes.map(knowledgeCard).join("")}
    </section>
  `);
}

function knowledgeCard(item) {
  const labels = text.knowledgeCard;
  const codeKey = (item.code || "").toLowerCase();
  const en = SUBTYPES_EN[codeKey] || {};
  const titleEn = TITLE_EN[codeKey];
  const organismQEn = ORGANISM_Q_EN[item.organismQuestion] || item.organismQuestion;
  const lifeThemeEn = en.lifeTheme || item.lifeTheme;
  const essenceQualitiesEn = en.essenceQualities || (item.essence ? item.essence.qualities : []);
  return `
    <article class="knowledge-card ${item.visualPages ? "knowledge-card--expanded" : ""}">
      <div class="knowledge-card__top">
        <span>${enCode(item.code)}</span>
        <em class="${item.status === "needs_review" ? "needs-review" : ""}">${statusLabel(item.status)}</em>
      </div>
      <h2>${titleEn || item.title}</h2>
      <p class="animal">${labels.animalPrefix} ${item.animal}</p>
      <p class="source-line">${item.pages}</p>
      ${subtypeDetails[item.code.toLowerCase()] ? `<button class="card-open" data-route="subtype/${item.code.toLowerCase()}">${text.subtypePage.meinKompassTitle} open →</button>` : ""}
      ${item.sourceCoverage ? sourceCoverageSection(item.sourceCoverage) : ""}
      ${item.contentModules ? contentModuleSection(item.contentModules, item.code) : ""}
      ${item.remedyCards ? remedyCardSection(item.remedyCards) : ""}
      <div class="knowledge-section organism">
        <strong>${labels.organismQuestion}</strong>
        <p>${organismQEn}</p>
      </div>
      <div class="knowledge-section subtype-question">
        <strong>${labels.subtypeQuestion}</strong>
        <p>${SUBTYPE_Q_EN[codeKey] || item.subtypeQuestion}</p>
      </div>
      <div class="knowledge-section">
        <strong>${labels.coreSentence}</strong>
        <p>${en.integrationSentence || item.coreSentence_en || item.coreSentence}</p>
      </div>
      <div class="knowledge-section">
        <strong>${labels.lifeTheme}</strong>
        <ul>${lifeThemeEn.map((entry) => `<li>${entry}</li>`).join("")}</ul>
      </div>
      <div class="knowledge-section">
        <strong>${labels.practice}</strong>
        <p>${PRACTICE_EN[codeKey] || item.practice}</p>
      </div>
      ${item.signature ? `
        <div class="knowledge-section">
          <strong>${item.signature.title}</strong>
          <p>${item.signature.text}</p>
        </div>
      ` : ""}
      ${item.essence ? `
        <div class="knowledge-section essence-box">
          <strong>${(ESSENCE_EN[codeKey] || {}).title || item.essence.title}</strong>
          <p>${(ESSENCE_EN[codeKey] || {}).sentence || item.essence.sentence}</p>
          <ul>${essenceQualitiesEn.map((entry) => `<li>${entry}</li>`).join("")}</ul>
        </div>
      ` : ""}
      ${item.woundBehindPassion ? woundBehindPassionSection(item.woundBehindPassion, item.code) : ""}
      ${(item.heilmittel || item.remedies)
          ? hasHeilwissen()
            ? (item.heilmittel ? heilmittelSection(item.heilmittel, oelForType(item.code), item.code) : `
        <div class="knowledge-section">
          <strong>${labels.remedies}</strong>
          <p>${item.remedies.join(" · ")}</p>
        </div>
      `)
            : heilwissenLock()
          : ""}
      ${item.visualPages ? visualPageSection(item.visualPages, item.code) : ""}
      ${(item.mediaGroups || item.mediaResources)
          ? hasHeilwissen()
            ? (item.mediaGroups ? mediaGroupSection(item.mediaGroups) : mediaResourceSection(item.mediaResources))
            : heilwissenLock("Musik & Klang")
          : ""}
      <div class="review-box">
        <strong>${labels.review}</strong>
        ${item.needsReview.length ? `<ul>${item.needsReview.map((entry) => `<li>${entry}</li>`).join("")}</ul>` : `<p>${labels.noRequiredReviews}</p>`}
      </div>
    </article>
	  `;
}


