function sechzigSekundenScanPage() {
  const steps = [
    { title:"Step 1 &ndash; The Visible Layer", q:"&bdquo;What does the person want you to believe about who they are?&ldquo; (Persona &hellip;)",
      vals:["moral/right","helpful/needed","successful/valuable","special/unique","competent/knowledgeable","loyal/watchful","free/happy","strong/independent","harmonious/serene"] },
    { title:"Step 2 &ndash; Affect Under Pressure", q:"&bdquo;What happens when irritated?&ldquo; (Reaction &hellip;)",
      vals:["corrects/criticizes","clings/binds","pushes/speeds up","takes offense/dramatizes","distances/isolates itself","doubts/hedges","evades/deflects","pressures/confronts","calms/smooths over"] },
    { title:"Step 3 &ndash; The Core Question", q:"&bdquo;What is this person protecting themselves from?&ldquo; (Fear/avoidance of &hellip;)",
      vals:["being flawed","worthlessness","insignificance","being ordinary","being overwhelmed","insecurity","pain/loss","vulnerability","conflict/separation"] },
  ];
  const rowsHtml = steps.map(s => `
    <div style="margin-bottom:1.1rem;">
      <p style="margin:0 0 .5rem;font-weight:700;color:var(--copper);">${s.title}</p>
      <p style="margin:0 0 .6rem;font-size:.88rem;font-style:italic;color:var(--muted);">${s.q}</p>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:.4rem;">
        ${s.vals.map((v,i) => `<div style="background:var(--paper);border-radius:6px;padding:.4rem .6rem;font-size:.82rem;"><strong>Type ${i+1}:</strong> ${v}</div>`).join("")}
      </div>
    </div>
  `).join("");

  return shell(`
    ${pageHeader("60-sekunden-scan")}
    <section class="narrow">
      <p class="eyebrow">Charts &middot; Typing</p>
      <h1>60-Second Fixation Scan</h1>
      <p class="lead-small">To the Enneagram type in three steps: Which persona does the person show? How do they react under pressure? What are they protecting themselves from? This quick overview helps to classify a type quickly.</p>
      <div class="psycho-img-wrap" style="margin-top:1.5rem;">
        <img src="../assets/schaubilder/scan/60-sekunden-scan.jpg"
             alt="60-Second Fixation Scan"
             class="psycho-img" />
      </div>
      <div style="max-width:640px;margin:1.5rem auto 0;">
        ${rowsHtml}
        <p style="font-size:.85rem;color:var(--muted);text-align:center;margin-top:.5rem;">Persona: &bdquo;I am &hellip;&ldquo; &nbsp;&middot;&nbsp; Avoidance: &bdquo;I must not &hellip;&ldquo;</p>
      </div>
      ${bookTip("die-praxis-der-typbestimmung-taschenbuch", "A fast, reliable path to typing &ndash; persona, reaction under pressure, and core fear for all 9 types.", "Die Praxis der Typbestimmung")}
      ${relatedLinks([
        {route:"enneagramm-profiling", label:"Enneagram Profiling"},
        {route:"aufmerksamkeitsfokus", label:"Focus of Attention"},
        {route:"differenzierung", label:"Differentiation"},
      ])}
    </section>
  `);
}

function mikroimpresionenPage() {
  const typen = [
    { nr:1, name:"The Perfectionist",
      se:"The gaze is alert, scrutinizing, never fully relaxed – as if constantly checking whether everything is correct. The jawline is often slightly tense; the smile is restrained and careful. The body is upright, almost too upright. One feels an inner tension that manifests outwardly as correctness.",
      so:"An engaged, teaching-convincing gaze. The body shows posture in the literal sense – upright, demonstratively clear. This person wants to be a role model, and facial expressions convey this directly: seriousness, adherence to principles, a quiet sense of mission.",
      sx:"Intensity and control in one. The gaze is demanding, almost challenging. Body tension is high, facial expressions vacillate between strict composure and charged passion. Willingness to compromise is nowhere to be seen – but all the more inner heat." },
    { nr:2, name:"The Helper",
      se:"A soft, striving smile that simultaneously asks: Is it good? Do you like it? The eyes seek resonance. The upper body leans slightly forward – an almost imperceptible gesture of attentiveness. One senses care, but also a delicate neediness underneath.",
      so:"This variant beams. The eyes are large, the facial expression lively and inviting. The whole body speaks: „I am here for you.“ Compassion becomes visible and palpable – a presence that emotionally organizes a room without being loud about it.",
      sx:"The gaze is deeper, more penetrating, less general. It seeks one person, not a group. Body language is emotionally charged, physically present. Closeness is not merely offered – it is sought, sometimes urgently." },
    { nr:3, name:"The Achiever",
      se:"Hardly a movement that isn't calculated. Facial expressions are smooth and controlled; the smile fits perfectly. Body tension is goal-oriented, not defensive. What appears outwardly as efficiency often comes at a price within: closeness is not displayed because it could disrupt the performance.",
      so:"Here someone shines. Facial expressions are radiant, the expression magnetic – a living image presentation. The body is designed for impact and knows it. You want to look, you want to listen. This is no accident.",
      sx:"A gaze that sticks. Physically present, charming, with a touch of dominance. This person knows what attractiveness is – and uses it. The seductive quality is not necessarily meant romantically, but it is there." },
    { nr:4, name:"The Individualist",
      se:"A quiet that is not empty – rather filled with inner life. The gaze sometimes wanders off into the distance; facial expressions are reserved, almost tinged with melancholy. Body language soft, sometimes as if collapsed inward. One senses someone who feels a lot and shows little.",
      so:"Completely different: expressive, dramatic, searching. The eyes speak loudly. Gestures emphasize what is felt. This variant carries its depth outward – not for show, but as an honest expression of an inner world that always threatens to overflow.",
      sx:"Yearning gaze, sensual presence. The body seeks closeness, then retreats, then attracts again. The interplay between attraction and withdrawal is not strategic – it is the very nature of this variant." },
    { nr:5, name:"The Observer",
      se:"Few facial expressions, much perception. The gaze is averted or directed inward; the body pulls back slightly. Energy is conserved – used sparingly, carefully dosed. Those who look closely recognize a sharp, registering mind underneath.",
      so:"Alert gaze with a slight furrowed brow – as if quietly cataloging the situation. Body language reserved, but not off-putting. They are present, taking in, evaluating – they just don't show it. A quiet analyst.",
      sx:"Here something breaks through. The gaze is piercing, almost charged – a concentrated intensity that doesn't explain itself. Body tension high. Entering into a conversation or an idea can feel almost physical. Intellectual merging as the ultimate intimate space." },
    { nr:6, name:"The Loyalist",
      se:"The gaze meets yours, scrutinizes you, perhaps distrusts you. The brow is often slightly furrowed, the posture defensive – arms crossed or shoulders slightly raised. This person is attentive, vigilant, quiet. Not hostile, but certainly not careless.",
      so:"The eyes scan the room, seeking group context. Facial expressions react to moods, almost like a seismograph. Body language wants to signal belonging – I am part of this. Commitment as a sense of security.",
      sx:"Confrontational, testing, direct. The gaze does not break easily. Body language is demanding, alternating between attack and withdrawal. This variant wants to find out if you can keep what you promise – and tests it openly." },
    { nr:7, name:"The Enthusiast",
      se:"Joyful facial expression with a touch of control – not uncontrolled, but agile. Body language fast, targeted, full of energy. There is always a next point, a next thought. The joy is real, but it is also efficient.",
      so:"Expressive, lively, contagious. Grand gestures, a gaze that invites. This person wakes up a room. Enthusiasm is their natural territory – and they share it generously. Charm as a natural state.",
      sx:"A playful yet intense gaze. Body language dynamic, sometimes seductive. One senses someone seeking adventure – intellectually, emotionally, or physically. The energy seeks its exchange." },
    { nr:8, name:"The Challenger",
      se:"A fixed gaze that rarely wavers. Facial expressions are controlled, body tension defensively aggressive at the same time. Outward steadfastness, behind which often lies more vulnerability than is visible. Showing weaknesses is not an option.",
      so:"Strong presence – one senses this person before they speak. The gaze is vigilant, the body occupies space, the posture is clear and protective. Not dominance for the sake of dominance, but responsibility as a lived matter of course.",
      sx:"Magnetic, raw, passionate. The gaze hits you directly. Body language is designed for confrontation or co-optation – sometimes both. One senses: this person is fully present. That can be liberating or overwhelming." },
    { nr:9, name:"The Peacemaker",
      se:"Gentle, relaxed, almost slumberingly warm. Facial expressions are calm, body language soft and unclenched. One feels comfortable in this proximity – but sometimes wonders: What is this person really thinking? The inner agenda remains invisible.",
      so:"An open, connecting gaze – balancing, mediating. The body stays centered, seeking balance. This person wants everyone to stay. Sometimes so much so that they almost disappear themselves.",
      sx:"Soft, but with an underlying attraction. The gaze seeks connection, draws you in without demanding. Body language is inviting, charmingly passive. Those who look closer discover a calm yet genuine intensity underneath." },
  ];

  const farben = { 1:"#8b5e3c", 2:"#9e4a6a", 3:"#7a6a30", 4:"#5a7058", 5:"#3a6b8a", 6:"#6a5a8a", 7:"#8a6a2a", 8:"#7a3a3a", 9:"#4a7a6a" };

  const cards = typen.map(t => {
    const col = farben[t.nr] || "var(--copper)";
    return `
      <div style="margin-bottom:3rem;">
        <div style="display:flex;align-items:center;gap:.7rem;margin-bottom:1rem;">
          <span style="display:inline-flex;align-items:center;justify-content:center;width:2rem;height:2rem;border-radius:50%;background:${col};color:#fff;font-weight:800;font-size:.9rem;flex-shrink:0;">${t.nr}</span>
          <h2 style="font-size:1.1rem;font-weight:700;color:var(--ink);margin:0;">Type&nbsp;${t.nr} &ndash; ${t.name}</h2>
        </div>
        <img src="${CDN}assets/mikroimpressionen-${t.nr}.jpg"
          alt="Mikroimpressionen Typ ${t.nr}"
          style="width:100%;border-radius:10px;margin-bottom:1.1rem;display:block;" />
        <div style="display:grid;gap:.7rem;">
          ${[["SP","Self-Preservation",t.se],["SO","Social",t.so],["SX","Sexual/Partnership",t.sx]].map(([code,label,text]) => `
            <div style="border-left:3px solid ${col};padding:.6rem .9rem;background:var(--paper);border-radius:0 6px 6px 0;">
              <div style="font-size:.75rem;font-weight:800;color:${col};letter-spacing:.06em;margin-bottom:.3rem;">${code} \xb7 ${label}</div>
              <p style="margin:0;font-size:.85rem;line-height:1.7;color:var(--ink);">${text}</p>
            </div>
          `).join("")}
        </div>
      </div>
    `;
  }).join("");

  return shell(`
    ${pageHeader("mikroimpressionen")}
    <div style="max-width:680px;margin:0 auto;padding:0 1rem 3rem;">
      <p class="eyebrow">Charts &middot; Profiling</p>
      <h1 class="section-title">Mikroimpressionen der 27 Enneagramm-Subtypes</h1>
      <p class="psycho-intro">Long before someone speaks, they are already readable. Facial expressions, gaze, and bodily tension betray the structure underneath &ndash; if you know what to look for. This overview shows for all 27 Enneagram subtypes how their inner pattern expresses itself outwardly: not via self-reports, but via immediately perceptible signals. Each chart shows a type, and each description names the peculiarities of the three instinct variants.</p>
      <div style="border-left:3px solid var(--gold);padding:.7rem 1rem;margin-bottom:2rem;background:var(--paper);border-radius:0 6px 6px 0;font-size:.85rem;color:var(--muted);font-style:italic;">These descriptions are phenomenological sketches, not diagnoses. They sharpen observation &ndash; they do not replace a personal typing conversation.</div>
      ${cards}
      ${relatedLinks([
        {route:"nonverbale-signale", label:"Nonverbal Signals"},
        {route:"aufmerksamkeitsfokus", label:"Attention Focus"},
        {route:"enneagramm-profiling", label:"Enneagram Profiling"},
      ])}
    </div>
  `);
}

function mangelgefuehlePage() {
  return shell(`
    ${pageHeader("mangelgefuehle")}
    <section class="narrow">
      <p class="eyebrow">Charts &middot; Depth Psychology</p>
      <h1>Feelings of Deficiency of the 9 Enneagram Types</h1>
      <p class="lead-small">Every Enneagram type carries an unconscious inner feeling of deficiency &ndash; a deep sense that something essential is missing. Out of this deficiency arises the characteristic external striving that drives the type.</p>
      <div class="psycho-img-wrap" style="margin-top:1.5rem;">
        <img src="../assets/schaubilder/mangelgefuehle/mangelgefuehle.jpg"
             alt="Enneagram types and their unconscious inner feelings of deficiency"
             class="psycho-img" />
      </div>
      <div style="max-width:640px;margin:0 auto 1.5rem;font-size:.92rem;line-height:1.8;color:var(--ink);">
        <p>Each type carries the felt lack of exactly what it then chases in the outer world: Type 9 feels a lack of harmony/peace, and so strives for harmony outside. Type 1 feels a lack of perfection/completeness, and so strives for perfection outside. Type 2 feels a lack of love/being loved, and so strives for love outside. Type 3 feels a lack of success/outer recognition, and so strives for success outside. Type 4 feels a lack of individuality/distinctiveness, and so strives for individuality outside. Type 5 feels a lack of knowledge/wisdom, and so strives for knowledge outside. Type 6 feels a lack of security/trust, and so strives for security outside. Type 7 feels a lack of fun/joy of life, and so strives for fun outside. Type 8 feels a lack of power/control, and so strives for power outside.</p>
      </div>
      ${bookTip("wer-du-wirklich-bist-band-1", "Why the outward striving never fills the inner lack &ndash; and how each type finds its way back to true fullness.", "Wer du wirklich bist")}
      ${relatedLinks([
        {route:"frustrationen", label:"Frustrations"},
        {route:"intrinsisches-verlangen", label:"Intrinsic Desires"},
        {route:"angst-essenz", label:"Fear & Essence"},
      ])}
    </section>
  `);
}

function perspektivenPage() {
  const PERSP = [
    { nr:9, name:"The Accommodating Diplomat", quote:"We are often annoyed that you only very rarely take a clear position!" },
    { nr:1, name:"The Consistent Perfectionist", quote:"We often feel corrected, criticized, or reprimanded by you!" },
    { nr:2, name:"The Caring Love-Seeker", quote:"We often feel manipulated by you in some form!" },
    { nr:3, name:"The Successful Doer", quote:"We often experience you as deceptive and emotionally unreachable, at times even dismissive!" },
    { nr:4, name:"The Intense Artist", quote:"We often experience you as a bit overly emotional and entangled with you in relationship dramas!" },
    { nr:5, name:"The Competent Thinker", quote:"We often feel observed by you, somewhat looked down upon, and emotionally neglected!" },
    { nr:6, name:"The Loyal Hero", quote:"We often feel tested by you on reliability, and we also often sense your doubt and distrust!" },
    { nr:7, name:"The Inspiring Golden Child", quote:"We often find you a bit superficial and often not very reliable!" },
    { nr:8, name:"The Active Guardian", quote:"We often feel dominated and controlled by you!" },
  ];
  const cardsHtml = PERSP.sort((a,b)=>a.nr-b.nr).map(p => `
    <div style="margin-bottom:.9rem;padding:.75rem 1rem;background:var(--paper);border-left:3px solid var(--copper);border-radius:0 8px 8px 0;">
      <p style="margin:0 0 .3rem;font-weight:700;color:var(--copper);">Type ${p.nr} &ndash; ${p.name}</p>
      <p style="margin:0;font-size:.9rem;font-style:italic;line-height:1.6;">&bdquo;${p.quote}&ldquo;</p>
    </div>
  `).join("");

  return shell(`
    ${pageHeader("perspektiven")}
    <section class="narrow">
      <p class="eyebrow">Charts &middot; Blind Spots</p>
      <h1>How Others Experience the Enneagram Types</h1>
      <p class="lead-small">What do others see in us that we barely perceive ourselves? This overview shows which statements fellow human beings repeatedly make about each Enneagram type &ndash; a mirror for one's own blind spot.</p>
      <div class="psycho-img-wrap" style="margin-top:1.5rem;">
        <img src="../assets/schaubilder/perspektiven/perspektiven-mitmenschen.jpg"
             alt="Enneagram types and the perspectives of the people around them"
             class="psycho-img" />
      </div>
      <div style="max-width:640px;margin:1.5rem auto 0;">
        ${cardsHtml}
      </div>
      ${bookTip("der-code-deiner-persoenlichkeit", "Why your blind spot is so hard to see on your own &ndash; and how each type learns to recognize what others already notice.", "Der Code deiner Persönlichkeit")}
      ${relatedLinks([
        {route:"schaubilder-als-spiegel", label:"Charts as Mirrors"},
        {route:"interessante-erkenntnisse", label:"Interesting Insights"},
        {route:"befreiende-fragen", label:"Liberating Questions"},
      ])}
    </section>
  `);
}

const INSTINKT_LABEL = { se: "Self-Preservation", so: "Social", sx: "Sexual" };
const INSTINKT_KURZ  = { se: "SP", so: "SO", sx: "SX" };

function subtypChecklistePage() {
  const parts = state.route.split("/");
  const typNr = parts[1] ? parseInt(parts[1]) : null;
  const inst  = parts[2] || null; // "se" | "so" | "sx"

  // Ebene 3: einzelne Checkliste groß
  if (typNr && inst && INSTINKT_LABEL[inst]) {
    const code = `${inst}${typNr}`;
    return shell(`
      ${pageHeader("subtypen-checklisten")}
      <div class="psycho-detail">
        <button class="ghost-link psycho-back" data-route="subtypen-checklisten/${typNr}">← Type ${typNr} Subtypes</button>
        <h1 class="psycho-detail__title">Type ${typNr} · ${INSTINKT_LABEL[inst]} (${INSTINKT_KURZ[inst]}${typNr})</h1>
        <div class="psycho-img-wrap">
          <img src="${CDN}assets/schaubilder/subtypen-checklisten/${code}.jpg"
               alt="Checklist ${INSTINKT_KURZ[inst]}${typNr}"
               class="psycho-img" />
        </div>
      </div>
    `);
  }

  // Ebene 2: 3 Subtypes eines Typs
  if (typNr && typNr >= 1 && typNr <= 9) {
    return shell(`
      ${pageHeader("subtypen-checklisten")}
      <div class="psycho-wrap">
        <button class="ghost-link psycho-back" data-route="subtypen-checklisten">← All Types</button>
        <p class="eyebrow">Subtype Checklists · Type ${typNr}</p>
        <h1 class="section-title">Type ${typNr} &ndash; Which Subtype Am I?</h1>
        <p class="psycho-intro">Choose an instinctual focus and check against the checklist how well the statements apply to you.</p>
        <div class="psycho-grid psycho-grid--3">
          ${["se","so","sx"].map(ins => `
            <button class="psycho-card psycho-card--inst" data-route="subtypen-checklisten/${typNr}/${ins}">
              <span class="psycho-card__nr">${INSTINKT_KURZ[ins]}${typNr}</span>
              <span class="psycho-card__name">${INSTINKT_LABEL[ins]}</span>
              <span class="psycho-card__arrow">→</span>
            </button>
          `).join("")}
        </div>
      </div>
    `);
  }

  // Ebene 1: Typauswahl 1&ndash;9
  return shell(`
    ${pageHeader("subtypen-checklisten")}
    <div class="psycho-wrap">
      <p class="eyebrow">Charts · Subtype Checklists</p>
      <h1 class="section-title">Subtype Checklists</h1>
      <p class="psycho-intro">Which of the 27 subtypes describes you most accurately? Choose your main type &ndash; then you can compare the three subtypes and check the checklists to see what applies to you.</p>
      <div class="psycho-grid">
        ${[1,2,3,4,5,6,7,8,9].map(n => `
          <button class="psycho-card" data-route="subtypen-checklisten/${n}">
            <span class="psycho-card__nr">${n}</span>
            <span class="psycho-card__name">${TYPNAMEN_MOTIV[n]}</span>
            <span class="psycho-card__arrow">→</span>
          </button>
        `).join("")}
      </div>
      ${relatedLinks([
        {route:"subtypen-schaubilder", label:"Subtype Charts"},
        {route:"bedeutung-27-subtypen", label:"Bedeutung der 27 Subtypes"},
        {route:"triadendefizite", label:"Triadendefizite"},
      ])}
    </div>
  `);
}

