        // Leichtes Vibrato
        const vib = ctx.createOscillator(); const vibG = ctx.createGain();
        vib.frequency.value = 0.5 + i * 0.08; vibG.gain.value = schnurrFreq * mult * 0.01;
        vib.connect(vibG); vibG.connect(o.frequency);
