          g.gain.linearRampToValueAtTime(0.12, ctx.currentTime + 0.1);
          g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.65);
          o.connect(g); g.connect(master); o.start(); o.stop(ctx.currentTime + 0.7);
